public static int binarySearch(int[] arr, int target) {
    int low = 0;                          // start of the search area
    int high = arr.length - 1;            // end of the search area

    while (low <= high) {                 // keep checking while an area remains
        int mid = low + (high - low) / 2; // safe middle point
        if (arr[mid] == target) {         // middle value matches
            return mid;                   // we found it
        } else if (arr[mid] < target) {   // target is bigger
            low = mid + 1;                 // search the right half
        } else {                           // target is smaller
            high = mid - 1;                // search the left half
        }
    }
    return -1;                             // target is not in the list
}

